const defaultProjectWorkflowRelationLimit = 100

// projectWorkflowReader is deliberately narrower than client.Client. Workflow
// health must reflect current Plane state, so the only read operation exposed
// here bypasses the response cache.
type projectWorkflowReader interface {
	GetNoCache(context.Context, string, map[string]string) (json.RawMessage, error)
}

type workflowIssueIdentity struct {
	ID         string `json:"id"`
	Identifier string `json:"identifier,omitempty"`
	Name       string `json:"name,omitempty"`
}

type workflowBlockerEntry struct {
	Issue     workflowIssueIdentity   `json:"issue"`
	BlockedBy []workflowIssueIdentity `json:"blocked_by,omitempty"`
	Blocking  []workflowIssueIdentity `json:"blocking,omitempty"`
}

type workflowBlockerReport struct {
	ProjectID       string                 `json:"project_id"`
	ScannedIssues   int                    `json:"scanned_issues"`
	AvailableIssues int                    `json:"available_issues"`
	RelationLimit   int                    `json:"relation_limit"`
	Truncated       bool                   `json:"truncated"`
	BlockedCount    int                    `json:"blocked_count"`
	BlockingCount   int                    `json:"blocking_count"`
	RelationEdges   int                    `json:"relation_edges"`
	Entries         []workflowBlockerEntry `json:"entries"`
}

type workflowProjectHealthReport struct {
	Project struct {
		ID         string `json:"id"`
		Identifier string `json:"identifier,omitempty"`
		Name       string `json:"name,omitempty"`
	} `json:"project"`
	IssueCount        int            `json:"issue_count"`
	CompletedCount    int            `json:"completed_count"`
	CompletionPercent float64        `json:"completion_percent"`
	ByState           map[string]int `json:"by_state"`
	ByStateGroup      map[string]int `json:"by_state_group"`
	ByPriority        map[string]int `json:"by_priority"`
	Blockers          struct {
		ScannedIssues int `json:"scanned_issues"`
		RelationLimit int `json:"relation_limit"`
		BlockedCount  int `json:"blocked_count"`
		BlockingCount int `json:"blocking_count"`
		RelationEdges int `json:"relation_edges"`
	} `json:"blockers"`
}

type workflowState struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Group string `json:"group"`
}

func newWorkflowProjectHealthCmd(flags *rootFlags) *cobra.Command {
	var slug string
	var limit int
	cmd := &cobra.Command{
		Use:   "project-health <project_id>",
		Short: "Summarize live project completion, state, priority, and blocker health.",
		Long: `Build an aggregated project-health report from Plane's live project
summary, workflow states, work items, and bounded relation fan-out. Every GET
bypasses the local response cache. --limit caps relation requests, not the
number of work items included in status and completion metrics.`,
		Example: `  plane-pp-cli workflow project-health 6ff068e6-c73a-4a5e-923d-90b7dae1daac --limit 100`,
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		Args: cobra.ExactArgs(1),
		PreRunE: func(cmd *cobra.Command, args []string) error {
			if limit <= 0 {
				return usageErr(fmt.Errorf("--limit must be greater than zero"))
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			reader, resolvedSlug, err := newProjectWorkflowReader(flags, slug)
			if err != nil {
				return err
			}
			_ = resolvedSlug
			report, err := buildProjectHealth(cmd.Context(), reader, args[0], limit)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			return printProjectWorkflowResult(cmd, flags, report)
		},
	}
	cmd.Flags().StringVar(&slug, "slug", "", "Workspace slug; overridden by global --workspace (defaults to $"+envWorkspaceSlug+")")
	cmd.Flags().IntVar(&limit, "limit", defaultProjectWorkflowRelationLimit, "Maximum number of work-item relation GETs (must be positive)")
	return cmd
}

func newWorkflowBlockersCmd(flags *rootFlags) *cobra.Command {
	var slug string
	var limit int
	cmd := &cobra.Command{
		Use:   "blockers <project_id>",
		Short: "List live blocked-by and blocking relationships for a project.",
		Long: `Read all current project work items, then inspect at most --limit
relation endpoints using cache-bypassing GETs. The result excludes unrelated
relation types and work items with no blocked-by or blocking relationships.`,
		Example: `  plane-pp-cli workflow blockers 6ff068e6-c73a-4a5e-923d-90b7dae1daac --limit 100`,
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		Args: cobra.ExactArgs(1),
		PreRunE: func(cmd *cobra.Command, args []string) error {
			if limit <= 0 {
				return usageErr(fmt.Errorf("--limit must be greater than zero"))
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			reader, resolvedSlug, err := newProjectWorkflowReader(flags, slug)
			if err != nil {
				return err
			}
			_ = resolvedSlug
			issues, err := readProjectWorkflowPages(cmd.Context(), reader,
				fmt.Sprintf("/projects/%s/work-items/", args[0]))
			if err != nil {
				return classifyAPIError(err, flags)
			}
			report, err := buildBlockerReport(cmd.Context(), reader, args[0], issues, limit)
			if err != nil {
				return classifyAPIError(err, flags)
			}
			return printProjectWorkflowResult(cmd, flags, report)
		},
	}
	cmd.Flags().StringVar(&slug, "slug", "", "Workspace slug; overridden by global --workspace (defaults to $"+envWorkspaceSlug+")")
	cmd.Flags().IntVar(&limit, "limit", defaultProjectWorkflowRelationLimit, "Maximum number of work-item relation GETs (must be positive)")
	return cmd
}

func newProjectWorkflowReader(flags *rootFlags, localSlug string) (projectWorkflowReader, string, error) {
	slug := effectiveSlug(flags, localSlug)
	if slug == "" || slug == "my-workspace" {
		return nil, "", usageErr(fmt.Errorf("workspace not set: pass --workspace <slug>, --slug <slug>, export %s, or run 'plane-pp-cli workspaces use <slug>'", envWorkspaceSlug))
	}
	c, err := flags.newClient()
	if err != nil {
		return nil, "", err
	}
	applyClientSlug(c, slug)
	return c, slug, nil
}

func printProjectWorkflowResult(cmd *cobra.Command, flags *rootFlags, value any) error {
	data, err := json.Marshal(value)
	if err != nil {
		return err
	}
	return printOutputWithFlags(cmd.OutOrStdout(), data, flags)
}

func buildProjectHealth(ctx context.Context, reader projectWorkflowReader, projectID string, relationLimit int) (workflowProjectHealthReport, error) {
	var report workflowProjectHealthReport
	report.Project.ID = projectID
	report.ByState = map[string]int{}
	report.ByStateGroup = map[string]int{}
	report.ByPriority = map[string]int{}

	summaryRaw, err := reader.GetNoCache(ctx, fmt.Sprintf("/projects/%s/summary/", projectID), nil)
	if err != nil {
		return report, err
	}
	var summary map[string]any
	if err := json.Unmarshal(summaryRaw, &summary); err != nil {
		return report, fmt.Errorf("decoding project summary: %w", err)
	}
	report.Project.Name = firstString(summary, "name", "project_name")
	report.Project.Identifier = firstString(summary, "identifier", "project_identifier")

	stateRows, err := readProjectWorkflowPages(ctx, reader, fmt.Sprintf("/projects/%s/states/", projectID))
	if err != nil {
		return report, err
	}
	states := make(map[string]workflowState, len(stateRows))
	for _, raw := range stateRows {
		var state workflowState
		if json.Unmarshal(raw, &state) == nil && state.ID != "" {
			states[state.ID] = state
		}
	}

	issues, err := readProjectWorkflowPages(ctx, reader, fmt.Sprintf("/projects/%s/work-items/", projectID))
	if err != nil {
		return report, err
	}
	report.IssueCount = len(issues)
	for _, raw := range issues {
		var issue map[string]any
		if json.Unmarshal(raw, &issue) != nil {
			continue
		}
		stateID, stateName, stateGroup := issueState(issue, states)
		_ = stateID
		if stateName == "" {
			stateName = "unknown"
		}
		if stateGroup == "" {
			stateGroup = "unknown"
		}
		report.ByState[stateName]++
		report.ByStateGroup[stateGroup]++
		priority := strings.ToLower(firstString(issue, "priority"))
		if priority == "" {
			priority = "none"
		}
		report.ByPriority[priority]++
		if stateGroup == "completed" || firstString(issue, "completed_at") != "" {
			report.CompletedCount++
		}
	}
	if report.IssueCount > 0 {
		report.CompletionPercent = float64(report.CompletedCount) * 100 / float64(report.IssueCount)
	}

	blockers, err := buildBlockerReport(ctx, reader, projectID, issues, relationLimit)
	if err != nil {
		return report, err
	}
	report.Blockers.ScannedIssues = blockers.ScannedIssues
	report.Blockers.RelationLimit = blockers.RelationLimit
	report.Blockers.BlockedCount = blockers.BlockedCount
	report.Blockers.BlockingCount = blockers.BlockingCount
	report.Blockers.RelationEdges = blockers.RelationEdges
	return report, nil
}

func buildBlockerReport(ctx context.Context, reader projectWorkflowReader, projectID string, issues []json.RawMessage, relationLimit int) (workflowBlockerReport, error) {
	report := workflowBlockerReport{
		ProjectID:       projectID,
		AvailableIssues: len(issues),
		RelationLimit:   relationLimit,
		Truncated:       len(issues) > relationLimit,
		Entries:         []workflowBlockerEntry{},
	}
	scanCount := len(issues)
	if scanCount > relationLimit {
		scanCount = relationLimit
	}
	for _, raw := range issues[:scanCount] {
		issue := workflowIdentity(raw)
		if issue.ID == "" {
			continue
		}
		report.ScannedIssues++
		relationRaw, err := reader.GetNoCache(ctx,
			fmt.Sprintf("/projects/%s/work-items/%s/relations/", projectID, issue.ID), nil)
		if err != nil {
			return report, err
		}
		blockedBy, blocking, err := parseBlockingRelations(relationRaw)
		if err != nil {
			return report, fmt.Errorf("decoding relations for work item %s: %w", issue.ID, err)
		}
		if len(blockedBy) == 0 && len(blocking) == 0 {
			continue
		}
		report.BlockedCount += len(blockedBy)
		report.BlockingCount += len(blocking)
		report.RelationEdges += len(blockedBy) + len(blocking)
		report.Entries = append(report.Entries, workflowBlockerEntry{
			Issue: issue, BlockedBy: blockedBy, Blocking: blocking,
		})
	}
	return report, nil
}

// readProjectWorkflowPages exhausts Plane's cursor pagination using only
// GetNoCache. It intentionally does not use the generated data-source resolver,
// whose auto strategy may fall back to the synced store on a network error.
func readProjectWorkflowPages(ctx context.Context, reader projectWorkflowReader, path string) ([]json.RawMessage, error) {
	const maxPages = 1000
	var all []json.RawMessage
	cursor := ""
	for page := 0; page < maxPages; page++ {
		params := map[string]string{"per_page": "100"}
		if cursor != "" {
			params["cursor"] = cursor
		}
		raw, err := reader.GetNoCache(ctx, path, params)
		if err != nil {
			return nil, err
		}
		items, next, hasMore := extractPageItems(raw, "cursor")
		if items == nil {
			return nil, fmt.Errorf("unexpected paginated response from %s", path)
		}
		all = append(all, items...)
		if !hasMore && next == "" {
			return all, nil
		}
		if next == "" {
			return nil, fmt.Errorf("paginated response from %s says more data exists but has no next cursor", path)
		}
		if next == cursor {
			return nil, fmt.Errorf("paginated response from %s repeated cursor %q", path, next)
		}
		cursor = next
	}
	return nil, fmt.Errorf("pagination from %s exceeded %d pages", path, maxPages)
}

func workflowIdentity(raw json.RawMessage) workflowIssueIdentity {
	var item map[string]any
	if json.Unmarshal(raw, &item) != nil {
		return workflowIssueIdentity{}
	}
	return identityFromMap(item)
}

func identityFromMap(item map[string]any) workflowIssueIdentity {
	identity := workflowIssueIdentity{
		ID:   firstString(item, "id", "issue_id"),
		Name: firstString(item, "name", "title"),
	}
	identity.Identifier = firstString(item, "identifier")
	if identity.Identifier == "" {
		sequence := firstString(item, "sequence_id")
		projectIdentifier := firstString(item, "project_identifier", "project__identifier")
		if sequence != "" && projectIdentifier != "" {
			identity.Identifier = projectIdentifier + "-" + sequence
		} else {
			identity.Identifier = sequence
		}
	}
	return identity
}

func parseBlockingRelations(raw json.RawMessage) ([]workflowIssueIdentity, []workflowIssueIdentity, error) {
	var grouped map[string]json.RawMessage
	if err := json.Unmarshal(raw, &grouped); err != nil {
		return nil, nil, err
	}
	// Generated Plane reads may return the grouped relation object directly or
	// under the standard {"data": ...} response envelope.
	if data, ok := grouped["data"]; ok {
		var nested map[string]json.RawMessage
		if json.Unmarshal(data, &nested) == nil {
			grouped = nested
		}
	}
	blockedBy, err := relationIdentities(grouped["blocked_by"])
	if err != nil {
		return nil, nil, err
	}
	blocking, err := relationIdentities(grouped["blocking"])
	if err != nil {
		return nil, nil, err
	}
	return blockedBy, blocking, nil
}

func relationIdentities(raw json.RawMessage) ([]workflowIssueIdentity, error) {
	if len(raw) == 0 || string(raw) == "null" {
		return nil, nil
	}
	var values []json.RawMessage
	if err := json.Unmarshal(raw, &values); err != nil {
		return nil, err
	}
	out := make([]workflowIssueIdentity, 0, len(values))
	for _, value := range values {
		var scalarID string
		if json.Unmarshal(value, &scalarID) == nil {
			if scalarID != "" {
				out = append(out, workflowIssueIdentity{ID: scalarID})
			}
			continue
		}
		var item map[string]any
		if err := json.Unmarshal(value, &item); err != nil {
			return nil, err
		}
		// Some Plane serializers nest the related work item under issue or
		// related_issue; flattened serializers return the identity directly.
		for _, key := range []string{"issue", "related_issue", "related"} {
			if nested, ok := item[key].(map[string]any); ok {
				item = nested
				break
			}
		}
		identity := identityFromMap(item)
		if identity.ID != "" {
			out = append(out, identity)
		}
	}
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].ID < out[j].ID
	})
	return out, nil
}

func issueState(issue map[string]any, states map[string]workflowState) (id, name, group string) {
	switch value := issue["state"].(type) {
	case string:
		id = value
	case map[string]any:
		id = firstString(value, "id")
		name = firstString(value, "name")
		group = strings.ToLower(firstString(value, "group"))
	}
	if state, ok := states[id]; ok {
		if name == "" {
			name = state.Name
		}
		if group == "" {
			group = strings.ToLower(state.Group)
		}
	}
	return id, name, group
}

func firstString(values map[string]any, keys ...string) string {
	for _, key := range keys {
		switch value := values[key].(type) {
		case string:
			if value != "" {
				return value
			}
		case json.Number:
			return value.String()
		case float64:
			return strconv.FormatFloat(value, 'f', -1, 64)
		}
	}
	return ""
}
